void test_FR_019_01(void)
{
    alert_indicator_state_t state;
    alert_indicator_output_t output;

    memset(&state, 0, sizeof(state));

    output = alert_indicator_update(&state, 100U, MOTION_EVENT_SPEEDING);
    TEST_ASSERT_EQUAL_INT(MOTION_EVENT_SPEEDING, output.active_event);

    output = alert_indicator_update(&state, 100U, MOTION_EVENT_WIDE_TURN);
    TEST_ASSERT_EQUAL_INT(MOTION_EVENT_WIDE_TURN, output.active_event);

    output = alert_indicator_update(&state, 100U, MOTION_EVENT_UNSEEN_SPEED_BREAKER);
    TEST_ASSERT_EQUAL_INT(MOTION_EVENT_UNSEEN_SPEED_BREAKER, output.active_event);

    output = alert_indicator_update(&state, 100U, MOTION_EVENT_SUDDEN_BRAKING);
    TEST_ASSERT_EQUAL_INT(MOTION_EVENT_SUDDEN_BRAKING, output.active_event);

    output = alert_indicator_update(&state, 100U, MOTION_EVENT_SPEEDING);
    TEST_ASSERT_EQUAL_INT(MOTION_EVENT_SUDDEN_BRAKING, output.active_event);
}
